from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.core import EPCSim


class _EPCSimWrapper(ListAbstractionsWrapper):
    """
    All redirections for epcsim are contained inside this wrapper's properties
    """

    def __init__(self, tl_config):
        super(_EPCSimWrapper, self).__init__(tl_config)
        self._epcsim = self.get_instance(EPCSim, [self.tl_config.core])

    @property
    def addr(self):
        return self._epcsim.default_ssh_connection_details.addr

    @property
    def dir_path(self):
        return self._epcsim.dir_path

    @property
    def username(self):
        return self._epcsim.default_ssh_connection_details.username

    @property
    def password(self):
        return self._epcsim.default_ssh_connection_details.password

    @property
    def cfg_filename(self):
        return self._epcsim.cfg_filename

    @property
    def mme_ip(self):
        if self._epcsim.mme_ip is not None:
            return self._epcsim.mme_ip
        else:
            return '10.1.1.100'

    @property
    def tac(self):
        return self._epcsim.tac if self._epcsim.tac is not None else '788'

    @property
    def mnc(self):
        return self._epcsim.mnc if self._epcsim.mnc is not None else '489'

    @property
    def mcc(self):
        return self._epcsim.mcc if self._epcsim.mcc is not None else '311'
